import { Controller, HttpCode, Post, Req } from '@nestjs/common';
import type { Request } from 'express';
import { transaction } from '../common/db';
import { ApiError } from '../common/errors';
import { currentUser } from '../common/user';

// 가정: 파일 이름은 신고 유형과 귀속연월로 만든다 (BEHAVIOR.md 값의 출처: 계산, 가정).
// 가정: 파일 내용은 헤더 한 줄(유형|귀속연월|신고구분)과 신고 자료로 구성한다 (개발 담당자 결정).
const FILE_EXTENSION = '.txt';

@Controller('api/v1')
export class FnSfr02304Controller {
  @Post('/withholding-reports/:withholdingReportId/generate-file')
  @HttpCode(200)
  async generateWithholdingReportFile(@Req() req: Request) {
    const user = currentUser(req);
    user.require('급여 담당자');
    const idText = req.params['withholdingReportId'];
    if (!/^\d+$/.test(idText)) {
      throw new ApiError(400, 'VALIDATION_FAILED', '신고서 ID 형식이 올바르지 않습니다.');
    }
    return transaction(async (db) => {
      const rows = await db.query(
        `SELECT withholding_report_id AS "withholdingReportId",
                attribution_month AS "attributionMonth",
                report_division AS "reportDivision",
                report_type AS "reportType",
                status AS "status",
                report_data AS "reportData"
           FROM withholding_report
          WHERE withholding_report_id = CAST(:id AS bigint)`,
        { id: idText },
      );
      if (rows.length === 0) {
        throw new ApiError(404, 'WITHHOLDING_REPORT_NOT_FOUND', '신고서를 찾을 수 없습니다.');
      }
      const report = rows[0];
      if (report.status !== '확정') {
        throw new ApiError(409, 'WITHHOLDING_REPORT_NOT_CONFIRMED', '확정되지 않은 신고서는 전자신고 파일을 생성할 수 없습니다.');
      }
      const month = String(report.attributionMonth ?? '');
      const body = String(report.reportData ?? '').trim();
      if (!/^\d{6}$/.test(month)) {
        throw new ApiError(422, 'ELECTRONIC_FILE_FORMAT_INVALID', '귀속연월 형식이 올바르지 않아 전자신고 파일을 만들 수 없습니다.');
      }
      if (body === '') {
        throw new ApiError(422, 'ELECTRONIC_FILE_FORMAT_INVALID', '신고 자료가 비어 있어 전자신고 파일을 만들 수 없습니다.');
      }
      const fileName = `${report.reportType}_${month}${FILE_EXTENSION}`;
      const header = `${report.reportType}|${month}|${report.reportDivision}`;
      const fileContent = `${header}\n${body}\n`;
      return { fileName, fileContent };
    });
  }
}

