import { useState } from 'react';
import { Badge, Band, DataTable, Drawer, Field, Form, LookupSelect, Pairs, RefName, Select, TextInput, Tiles, call } from '../kit';
import type { PageProps, Row } from '../kit';

const TYPES: [string, string][] = [
  ['WITHHOLDING_STATUS', '원천징수이행상황'],
  ['TUITION_REPAYMENT', '학자금상환'],
  ['LOCAL_INCOME_TAX', '지방소득세 특별징수'],
  ['RESIDENT_TAX_EMPLOYER', '주민세 종업원분'],
  ['PAYMENT_STATEMENT', '지급명세서'],
  ['SUBMISSION_SUMMARY', '제출집계표'],
];

const typeName = (v: unknown) => TYPES.find((t) => t[0] === v)?.[1] ?? String(v ?? '');

type Panel =
  | { kind: 'create' }
  | { kind: 'edit'; row: Row }
  | { kind: 'confirm'; row: Row }
  | { kind: 'file'; row: Row };

export default function FnSfr02304Page({ role, notify }: PageProps) {
  // 조회 API가 없어 이 화면에서 처리한 신고서만 목록에 쌓는다.
  const [rows, setRows] = useState<Row[]>([]);
  const [panel, setPanel] = useState<Panel | null>(null);
  const [paydayId, setPaydayId] = useState<number | string>('');
  const [attributionMonth, setAttributionMonth] = useState('');
  const [paymentMonth, setPaymentMonth] = useState('');
  const [reportDivision, setReportDivision] = useState('');
  const [reportType, setReportType] = useState('');
  const [reportData, setReportData] = useState('');
  const [file, setFile] = useState<Row | null>(null);

  const patchRow = (id: unknown, change: Row) => {
    setRows((list) => list.map((r) => (r.withholdingReportId === id ? { ...r, ...change } : r)));
  };

  const close = () => {
    setPanel(null);
    setFile(null);
  };

  const openCreate = () => {
    setPaydayId('');
    setAttributionMonth('');
    setPaymentMonth('');
    setReportDivision('');
    setReportType('');
    setReportData('');
    setPanel({ kind: 'create' });
  };

  const openEdit = (row: Row) => {
    setReportData(String(row.reportData ?? ''));
    setPanel({ kind: 'edit', row });
  };

  const create = async () => {
    if (paydayId === '' || !attributionMonth || !reportDivision || !reportType) {
      throw new Error('급여 지급일, 귀속연월, 신고구분, 신고 유형은 필수입니다.');
    }
    if (!/^\d{6}$/.test(attributionMonth)) {
      throw new Error('귀속연월은 YYYYMM 형식으로 입력하세요.');
    }
    const res = await call('POST', '/withholding-reports', role, {
      paydayId,
      attributionMonth,
      paymentMonth,
      reportDivision,
      reportType,
      reportData,
    });
    setRows((list) => [
      {
        withholdingReportId: res.withholdingReportId,
        paydayId,
        attributionMonth,
        reportDivision,
        reportType,
        status: res.status,
        reportData: res.reportData,
      },
      ...list,
    ]);
    notify('신고서를 생성했습니다.');
    close();
  };

  const update = async (row: Row) => {
    if (!reportData.trim()) {
      throw new Error('신고 자료를 입력하세요.');
    }
    await call('PATCH', `/withholding-reports/${row.withholdingReportId}`, role, { reportData });
    patchRow(row.withholdingReportId, { reportData });
    notify('신고서를 수정했습니다.');
    close();
  };

  const confirm = async (row: Row) => {
    const res = await call('POST', `/withholding-reports/${row.withholdingReportId}/confirm`, role, {});
    patchRow(row.withholdingReportId, { status: res.status ?? '확정' });
    notify('신고서를 확정했습니다.');
    close();
  };

  const generate = async (row: Row) => {
    const res = await call('POST', `/withholding-reports/${row.withholdingReportId}/generate-file`, role, {});
    setFile(res);
    notify('전자신고 파일을 생성했습니다.');
  };

  const download = (f: Row) => {
    const blob = new Blob([String(f.fileContent ?? '')], { type: 'text/plain;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const a = document.createElement('a');
    a.href = url;
    a.download = String(f.fileName ?? 'report.txt');
    a.click();
    URL.revokeObjectURL(url);
  };

  const unconfirmed = rows.filter((r) => r.status === '미확정').length;
  const confirmed = rows.filter((r) => r.status === '확정').length;

  return (
    <div className="bento">
      <section className="box span-12">
        <h2>처리 현황</h2>
        <Tiles items={[['이번 작업 신고서', rows.length], ['미확정', unconfirmed], ['확정', confirmed]]} />
      </section>
      <section className="box span-12">
        <h2>지방세 신고서</h2>
        <Band total={rows.length}>
          <button type="button" onClick={openCreate}>신고서 생성</button>
        </Band>
        <DataTable
          rows={rows}
          empty="이 화면에서 처리한 신고서가 없습니다."
          columns={[
            { key: 'withholdingReportId', label: '원천세 신고서·신고 자료 ID' },
            { key: 'paydayId', label: '급여 지급일', render: (r) => <RefName table="payday" role={role} value={r.paydayId} /> },
            { key: 'attributionMonth', label: '귀속연월' },
            { key: 'reportDivision', label: '신고구분' },
            { key: 'reportType', label: '신고 유형', render: (r) => typeName(r.reportType) },
            { key: 'status', label: '확정 여부', render: (r) => <Badge value={r.status} /> },
            {
              key: 'actions',
              label: '처리',
              render: (r) => (
                <span>
                  {r.status === '미확정' && (
                    <button type="button" onClick={(e) => { e.stopPropagation(); openEdit(r); }}>수정</button>
                  )}
                  {r.status === '미확정' && (
                    <button type="button" onClick={(e) => { e.stopPropagation(); setPanel({ kind: 'confirm', row: r }); }}>확정</button>
                  )}
                  {r.status === '확정' && (
                    <button type="button" onClick={(e) => { e.stopPropagation(); setFile(null); setPanel({ kind: 'file', row: r }); }}>파일 생성</button>
                  )}
                </span>
              ),
            },
          ]}
        />
      </section>

      {panel?.kind === 'create' && (
        <Drawer title="신고서 생성" onClose={close}>
          <Form onSubmit={create} submit="생성">
            <Field label="급여 지급일" required>
              <LookupSelect table="payday" role={role} value={paydayId} onChange={setPaydayId} />
            </Field>
            <Field label="귀속연월" required hint="YYYYMM">
              <TextInput value={attributionMonth} onChange={setAttributionMonth} />
            </Field>
            <Field label="지급연월" hint="YYYYMM">
              <TextInput value={paymentMonth} onChange={setPaymentMonth} />
            </Field>
            <Field label="신고구분" required>
              <TextInput value={reportDivision} onChange={setReportDivision} />
            </Field>
            <Field label="신고 유형" required>
              <Select value={reportType} onChange={setReportType} options={TYPES} />
            </Field>
            <Field label="신고 자료" wide>
              <TextInput value={reportData} onChange={setReportData} multiline />
            </Field>
          </Form>
        </Drawer>
      )}

      {panel?.kind === 'edit' && (
        <Drawer title="신고서 수정" onClose={close}>
          <Form onSubmit={() => update(panel.row)} submit="수정">
            <Field label="신고 자료" required wide>
              <TextInput value={reportData} onChange={setReportData} multiline />
            </Field>
          </Form>
        </Drawer>
      )}

      {panel?.kind === 'confirm' && (
        <Drawer title="신고서 확정" onClose={close}>
          <Pairs
            items={[
              ['신고 유형', typeName(panel.row.reportType)],
              ['귀속연월', String(panel.row.attributionMonth ?? '')],
            ]}
          />
          <Form onSubmit={() => confirm(panel.row)} submit="확정" note="확정 후에는 정해진 절차 없이 수정할 수 없습니다.">
          </Form>
        </Drawer>
      )}

      {panel?.kind === 'file' && (
        <Drawer title="전자신고 파일 생성" onClose={close}>
          <Pairs
            items={[
              ['신고 유형', typeName(panel.row.reportType)],
              ['귀속연월', String(panel.row.attributionMonth ?? '')],
              ['확정 여부', <Badge key="s" value={panel.row.status} />],
            ]}
          />
          <Form onSubmit={() => generate(panel.row)} submit="파일 생성" note="생성한 파일은 내려받아 직접 제출합니다.">
          </Form>
          {file && (
            <div>
              <Pairs
                items={[
                  ['내려받을 전자신고 파일 이름', String(file.fileName ?? '')],
                  ['전자신고 파일 내용 또는 내려받기 경로', <pre key="c">{String(file.fileContent ?? '')}</pre>],
                ]}
              />
              <button type="button" onClick={() => download(file)}>파일 내려받기</button>
            </div>
          )}
        </Drawer>
      )}
    </div>
  );
}
